BEGIN;
DO $t$
DECLARE emp uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); lib uuid:=gen_random_uuid(); entrega uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); tr1 uuid:=gen_random_uuid(); tr2 uuid:=gen_random_uuid(); perfil uuid:=gen_random_uuid(); var uuid:=gen_random_uuid(); desp uuid; rec uuid; op uuid:=gen_random_uuid(); v jsonb; itens jsonb; consumo uuid;
BEGIN
 INSERT INTO auth.users(id,email,aud,role) VALUES(u,'homologacao-'||u::text||'@example.invalid','authenticated','authenticated');
 INSERT INTO public.empresas(id,nome) VALUES(emp,'Empresa fictícia teste lotes');
 INSERT INTO public.ew_niveis_acesso(empresa_id,nivel,nome) VALUES(emp,1,'Teste ADM') ON CONFLICT DO NOTHING;
 INSERT INTO public.ew_niveis_permissoes(empresa_id,nivel,chave,permitido) SELECT emp,1,chave,true FROM public.ew_permissoes_catalogo ON CONFLICT(empresa_id,nivel,chave) DO UPDATE SET permitido=true;
 INSERT INTO public.usuarios_empresas(empresa_id,usuario_id,perfil,nivel_acesso) VALUES(emp,u,'administrador',1);
 INSERT INTO public.usuarios_login(usuario_id,empresa_id,perfil,ativo,nome,login,nivel_acesso) VALUES(u,emp,'administrador',true,'Usuário fictício','teste-'||u::text,1);
 INSERT INTO public.ew_sessoes_unicas(usuario_id,sessao_auth_id) VALUES(u,sid);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'session_id',sid,'role','authenticated')::text,true);
 INSERT INTO public.obras(id,empresa_id,nome,codigo) VALUES(a,emp,'Obra fictícia A','TESTE-A'),(b,emp,'Obra fictícia B','TESTE-B'),(c,emp,'Obra fictícia C','TESTE-C');
 INSERT INTO public.ew_estoques_locais(empresa_id,obra_id,criado_por) VALUES(emp,a,u),(emp,b,u),(emp,c,u) ON CONFLICT DO NOTHING;
 INSERT INTO public.ew_locais_fisicos(empresa_id,nome,ativo) VALUES(emp,'G1',true),(emp,'G2',true),(emp,'G3',true) ON CONFLICT DO NOTHING;
 INSERT INTO public.ew_perfis(id,empresa_id,codigo,descricao,fabricante,comprimento_comercial_mm) VALUES(perfil,emp,'TESTE-01','Perfil fictício','Fabricante teste',6000);
 INSERT INTO public.ew_materiais_variacoes(id,empresa_id,tipo,perfil_id,ativo) VALUES(var,emp,'perfil',perfil,true);
 INSERT INTO public.ew_cem_obras_materiais(empresa_id,obra_id,tipo,perfil_id,variacao_id,quantidade_prevista,unidade_prevista) VALUES(emp,a,'perfil',perfil,var,3,'BARRA');
 INSERT INTO public.ew_fornecedores(empresa_id,nome,ativo) VALUES(emp,'Fornecedor fictício',true);
 INSERT INTO public.ew_obra_orcamento(empresa_id,obra_id,valor_total,aluminio,acessorios,vidros,outros,fabricacao,instalacao,criado_por) VALUES(emp,a,1000,1000,0,0,0,0,0,u);
 itens:=jsonb_build_array(jsonb_build_object('variacao_id',var,'comprimento_mm',6000,'quantidade',3,'valor_total',100));
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_receber_materiais_almox(emp,a,'aluminio',100,'Fornecedor fictício','TESTE',current_date,'Aquisição fictícia','G1',itens,op);
 desp:=(v->>'id')::uuid;
 v:=public.ew_receber_materiais_almox(emp,a,'aluminio',100,'Fornecedor fictício','TESTE',current_date,'Aquisição fictícia','G1',itens,op);
 IF NOT coalesce((v->>'ja_registrado')::boolean,false) THEN RAISE EXCEPTION 'Recebimento repetido não reconhecido'; END IF;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM set_config('role','postgres',true);
 IF (SELECT count(*) FROM ew_compras_interna.custo_lotes WHERE empresa_id=emp AND custo_centavos=10000 AND quantidade=3)<>1 THEN RAISE EXCEPTION 'Lote não criado'; END IF;
 SELECT r.id INTO STRICT rec FROM public.ew_nfe_recebimentos r JOIN public.ew_obra_despesas_itens i ON i.id=r.despesa_item_id WHERE i.despesa_id=desp;
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_transferir_estoque_entre_obras(emp,a,b,var,6000,'BARRA',2,'G1','G2','Transferência teste 1',tr1);
 v:=public.ew_transferir_estoque_entre_obras(emp,b,c,var,6000,'BARRA',1,'G2','G3','Transferência teste 2',tr2);
 PERFORM set_config('role','postgres',true);
 IF (SELECT count(*) FROM ew_compras_interna.custo_transferencias_integradas WHERE empresa_id=emp)<>2 THEN RAISE EXCEPTION 'Transferências sem apropriação'; END IF;
 IF (SELECT ajuste_centavos FROM ew_compras_interna.custo_transferencias_ajustes_financeiros WHERE empresa_id=emp AND obra_id=a) IS DISTINCT FROM -6667::numeric OR (SELECT ajuste_centavos FROM ew_compras_interna.custo_transferencias_ajustes_financeiros WHERE empresa_id=emp AND obra_id=b) IS DISTINCT FROM 3334::numeric OR (SELECT ajuste_centavos FROM ew_compras_interna.custo_transferencias_ajustes_financeiros WHERE empresa_id=emp AND obra_id=c) IS DISTINCT FROM 3333::numeric THEN RAISE EXCEPTION 'Apropriação sequencial incorreta'; END IF;
 PERFORM set_config('role','authenticated',true);
 BEGIN v:=public.ew_estornar_transferencia_entre_obras(emp,tr1,'Estorno prematuro',gen_random_uuid()); RAISE EXCEPTION 'TESTE_FALHOU'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='TESTE_FALHOU' THEN RAISE; END IF; END;
 BEGIN v:=public.ew_estornar_nfe_com_recebimentos(emp,rec,'Estorno prematuro',gen_random_uuid()); RAISE EXCEPTION 'TESTE_FALHOU'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='TESTE_FALHOU' THEN RAISE; END IF; END;
 PERFORM set_config('role','postgres',true);
 INSERT INTO public.ew_liberacoes_lotes(id,operacao_id,empresa_id,obra_id,data_liberacao,fabrica,arquivo_nome,itens_confirmados,materiais_confirmados,criado_por)
 VALUES(lib,gen_random_uuid(),emp,c,current_date,'G3','Teste de homologação','[]'::jsonb,jsonb_build_array(jsonb_build_object('variacao_id',var,'comprimento_mm',6000,'unidade','BARRA','quantidade',1,'local_estoque','G3')),u);
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_confirmar_entrega_producao(emp,c,'LOTE',lib,entrega);
 v:=public.ew_confirmar_entrega_producao(emp,c,'LOTE',lib,entrega);
 IF NOT coalesce((v->>'repetida')::boolean,false) THEN RAISE EXCEPTION 'Entrega duplicada'; END IF;
 PERFORM set_config('role','postgres',true);
 IF (SELECT count(*) FROM ew_compras_interna.custo_consumos_integrados WHERE empresa_id=emp AND quantidade=1)<>1 THEN RAISE EXCEPTION 'Consumo não integrado'; END IF;
 IF (SELECT sum(custo_centavos) FROM ew_compras_interna.custo_saldos_fragmentos WHERE empresa_id=emp AND local_id=c AND tipo='PRODUCAO') IS DISTINCT FROM 3333::numeric THEN RAISE EXCEPTION 'Custo consumido incorreto'; END IF;
 IF EXISTS(SELECT 1 FROM ew_compras_interna.custo_saldos_fragmentos WHERE empresa_id=emp AND local_id=c AND tipo='OBRA') THEN RAISE EXCEPTION 'Material consumido disponível'; END IF;
 IF (SELECT ajuste_centavos FROM ew_compras_interna.custo_transferencias_ajustes_financeiros WHERE empresa_id=emp AND obra_id=c) IS DISTINCT FROM 3333::numeric THEN RAISE EXCEPTION 'Despesa duplicada'; END IF;
 PERFORM set_config('role','authenticated',true);
 BEGIN v:=public.ew_estornar_transferencia_entre_obras(emp,tr2,'Estorno com consumo',gen_random_uuid()); RAISE EXCEPTION 'TESTE_FALHOU'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='TESTE_FALHOU' THEN RAISE; END IF; END;
 PERFORM set_config('role','postgres',true);
 SELECT id INTO STRICT consumo FROM public.ew_estoque_obras_movimentos WHERE empresa_id=emp AND lote_id=lib AND origem='PLANO_CORTE_LOTE';
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_cancelar_liberacoes_obra(c,'Cancelar liberação teste');
 v:=public.ew_estornar_movimento_obra(c,consumo,'Devolução da produção',gen_random_uuid());
 PERFORM set_config('role','postgres',true);
 IF NOT EXISTS(SELECT 1 FROM ew_compras_interna.custo_consumos_integrados WHERE empresa_id=emp AND movimento_id=consumo AND estornado_em IS NOT NULL) THEN RAISE EXCEPTION 'Consumo não estornado'; END IF;
 IF (SELECT sum(custo_centavos) FROM ew_compras_interna.custo_saldos_fragmentos WHERE empresa_id=emp AND local_id=c AND tipo='OBRA') IS DISTINCT FROM 3333::numeric THEN RAISE EXCEPTION 'Custo não retornou'; END IF;
 PERFORM set_config('role','authenticated',true);
 v:=public.ew_estornar_transferencia_entre_obras(emp,tr2,'Estorno teste 2',gen_random_uuid());
 v:=public.ew_estornar_transferencia_entre_obras(emp,tr1,'Estorno teste 1',gen_random_uuid());
 v:=public.ew_estornar_nfe_com_recebimentos(emp,rec,'Estorno integral teste',gen_random_uuid());
 PERFORM set_config('role','postgres',true);
 IF EXISTS(SELECT 1 FROM ew_compras_interna.custo_saldos_fragmentos WHERE empresa_id=emp) THEN RAISE EXCEPTION 'Saldo não zerado'; END IF;
END;$t$;
ROLLBACK;
SELECT 'devolução da produção e cadeia integral aprovadas' resultado;